    employee_id, start_date, end_date, leave_type, leave_status, used_days, reason
) VALUES (
            #{employeeId}, #{startDate}, #{endDate}, #{leaveType}, #{leaveStatus}, #{usedDays}, #{reason}
        )

mapper.select:
SELECT COUNT(*)
FROM leave_request
